 "faq.title":"Câu hỏi thường gặp",
 "faq":[["Game có miễn phí không?","Có. Tải và chơi hoàn toàn miễn phí."],["Có cần đăng ký không?","Không. Chạm Đăng nhập bằng Google, game tự tạo ID. Sau đó có thể đặt ID và mật khẩu trong Cài đặt > Tài khoản hoặc đăng ký ID trong game."],["Nhân vật có bị mất không?","Nhân vật lưu trên máy chủ nên xóa ứng dụng hay đổi máy vẫn còn. Trong thời gian thử nghiệm dữ liệu game có thể được điều chỉnh hoặc đặt lại."],["Game báo cần cập nhật?","Thường game tự tải bản vá khi mở. Nếu cần ứng dụng mới, hãy tải APK mới nhất tại đây và cài đè."],["Máy báo ứng dụng không an toàn?","Bản thử nghiệm cài ngoài Play Store. Hãy cho phép cài ứng dụng không rõ nguồn cho trình duyệt bạn dùng để tải."],["Máy nóng hoặc giật?","Bật Tự giảm tải trong Cài đặt > Đồ họa, chọn mức đồ họa thấp hơn hoặc giảm số người chơi hiển thị đầy đủ."],["Chơi trên iPhone được không?","Đang chuẩn bị; cách cài sẽ được công bố sớm."],["Báo lỗi thế nào?","Trong game vào Cài đặt > Báo cáo, chọn chủ đề rồi gửi, hoặc email ranmobile1th@gmail.com."]],
 "end.kicker":"Chiến trường đang chờ","end.title":"Học viện của bạn đang chờ","end.p":"Tải ngay hôm nay, lập bang hội cùng bạn bè và gặp nhau trong chiến tranh học viện.","foot.privacy":"Quyền riêng tư","foot.terms":"Điều khoản","foot.contact":"Liên hệ","pop.title":"Thử nghiệm mở đã bắt đầu","pop.sub":"Android · Đăng nhập bằng Google","pop.more":"Xem thêm",
